INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Grafikprozessoren immer schneller als CPUs sind?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von der Aufgabe"}, {"text": "Ja", "correct": false, "because": "CPUs besser bei sequenziellen Aufgaben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework wähle ich für plattformübergreifende parallele Berechnungen?', 3, '[{"text": "OpenCL", "correct": true, "because": "Unterstützt verschiedene Hardware"}, {"text": "CUDA", "correct": false, "because": "Nur Nvidia-GPUs"}, {"text": "DirectX", "correct": false, "because": "Primär für Grafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben profitieren besonders von paralleler Verarbeitung auf Grafikkarten?', 5, '[{"text": "Matrixmultiplikation", "correct": true, "because": "Hoch parallele Operation"}, {"text": "Bildverarbeitung", "correct": true, "because": "Viele Pixel gleichzeitig"}, {"text": "Einzelne Datenbankabfragen", "correct": false, "because": "Meist sequenziell"}, {"text": "Texteditor", "correct": false, "because": "Geringe Rechenlast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CUDA ist ein offener Standard. b) OpenCL unterstützt CPUs und GPUs.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "CUDA ist proprietär"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Grafikkarte für parallele Berechnungen auswähle?', 4, '[{"text": "Anzahl der Kerne", "correct": false, "because": "Entscheidend für Parallelität"}, {"text": "Speicherbandbreite", "correct": false, "because": "Beeinflusst Datenfluss"}, {"text": "Gehäusefarbe", "correct": true, "because": "Irrelevant für Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Grafikkarten nur für Spiele nützlich sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für wissenschaftliche Berechnungen"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal macht Grafikkarten für große Datenmengen geeignet?', 3, '[{"text": "Hohe Parallelität", "correct": true, "because": "Viele Kerne arbeiten gleichzeitig"}, {"text": "Hohe Taktfrequenz", "correct": false, "because": "Weniger relevant als Kerne"}, {"text": "Großer Cache", "correct": false, "because": "Sekundär bei GPUs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für parallele Berechnungen auf Grafikkarten entscheidend?', 5, '[{"text": "Viele Rechenkerne", "correct": true, "because": "Ermöglichen Parallelität"}, {"text": "Schneller Speicherzugriff", "correct": true, "because": "Reduziert Wartezeiten"}, {"text": "Hohe Auflösung", "correct": false, "because": "Nur für Grafik relevant"}, {"text": "Bluetooth-Unterstützung", "correct": false, "because": "Kein Rechenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Grafikkarten weniger präzise als CPUs sind und b) sie immer mehr Strom verbrauchen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GPUs opfern oft Präzision für Geschwindigkeit"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist kontextabhängig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine parallele Berechnung auf einer Grafikkarte?', 4, '[{"text": "Programmierschnittstelle", "correct": false, "because": "Wie CUDA oder OpenCL nötig"}, {"text": "Hohe Speicherbandbreite", "correct": false, "because": "Wichtig für Datenfluss"}, {"text": "Integrierte Webcam", "correct": true, "because": "Kein Rechenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist CUDA auf allen Grafikkarten verfügbar?', 2, '[{"text": "Nein", "correct": true, "because": "Nur auf Nvidia-GPUs"}, {"text": "Ja", "correct": false, "because": "Proprietär für Nvidia"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet parallele Verarbeitung auf Grafikkarten?', 4, '[{"text": "Schnellere Berechnungen", "correct": true, "because": "Viele Kerne gleichzeitig"}, {"text": "Hohe Parallelität", "correct": true, "because": "Optimiert für große Daten"}, {"text": "Kleinere Bauform", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Grafikkarten für KI-Training ungeeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Ideal für parallele Berechnungen"}, {"text": "Ja", "correct": false, "because": "Weit verbreitet in KI"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich eine Grafikkarte für wissenschaftliche Simulationen wähle?', 3, '[{"text": "Hohe Rechenleistung", "correct": true, "because": "Beschleunigt Simulationen"}, {"text": "Gute Kühlung", "correct": false, "because": "Sekundär wichtig"}, {"text": "RGB-Beleuchtung", "correct": false, "because": "Kein Leistungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Grafikkarten eignen sich für Vektorberechnungen. b) Sie ersetzen CPUs vollständig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "CPUs für andere Aufgaben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Problem löst parallele Verarbeitung auf Grafikkarten besonders gut?', 4, '[{"text": "Bildfilterung", "correct": true, "because": "Viele Pixel gleichzeitig bearbeitet"}, {"text": "Einzelthread-Aufgaben", "correct": false, "because": "Besser für CPUs"}, {"text": "Einfache Textverarbeitung", "correct": false, "because": "Geringe Parallelität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Grafikkarten für Kryptografie nützlich sind?', 2, '[{"text": "Ja", "correct": true, "because": "Gut für parallele Hash-Berechnungen"}, {"text": "Nein", "correct": false, "because": "Häufig verwendet"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist OpenCL einfacher zu lernen als CUDA?', 3, '[{"text": "Nein", "correct": true, "because": "Komplexität ähnlich, aber breiter einsetzbar"}, {"text": "Ja", "correct": false, "because": "Beide haben Lernkurve"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Speicher bei parallelen Berechnungen?', 4, '[{"text": "Schneller Datenzugriff", "correct": true, "because": "Reduziert Wartezeiten"}, {"text": "Hohe Kapazität", "correct": false, "because": "Wichtig, aber nicht primär"}, {"text": "Farbtiefe", "correct": false, "because": "Nur für Grafik relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass parallele Berechnungen immer fehlerfrei sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Treiberfehler oder Speicherprobleme möglich"}, {"text": "Ja", "correct": false, "because": "Fehlerquellen existieren"}]');
